def admit(active, waiting, budget, slots):
    # Check if any waiting booking exceeds the total budget
    for value in waiting:
        if value > budget:
            raise ValueError()

    admitted = []
    max_new = slots - len(active)

    for value in waiting:
        if len(admitted) >= max_new:
            break
        if sum(active) + sum(admitted) + value <= budget:
            admitted.append(value)
        else:
            break

    # Calculate remaining: waiting values not admitted (handle duplicates correctly)
    admitted_copy = list(admitted)
    remaining = []
    for v in waiting:
        if v in admitted_copy:
            admitted_copy.remove(v)
        else:
            remaining.append(v)

    return admitted, remaining

def endpoint(base_url, path):
    # Remove trailing slash from base
    base = base_url.rstrip('/')

    # Check if base already ends with exactly '/v1'
    if base.endswith('/v1'):
        # Already has /v1, just connect with path (without adding another /v1)
        return base + '/' + path.lstrip('/')
    else:
        # Need to insert /v1 before the path
        return base + '/v1/' + path.lstrip('/')

