def admit(active, waiting, budget, slots):
    if any(v > budget for v in waiting):
        raise ValueError("Reservation exceeds total budget")

    admitted = []
    current_sum = sum(active)
    available_slots = slots - len(active)

    for v in waiting:
        if len(admitted) >= available_slots:
            break
        if current_sum + v > budget:
            break
        admitted.append(v)
        current_sum += v

    return admitted, waiting[len(admitted):]

